css:
body{font-family:Arial,sans-serif;font-size:13px;color:#1a1a1a}
.pho-wrap{max-width:820px;margin:0 auto}
.stmt-header{text-align:center;border-bottom:3px solid #2c5f2e;padding-bottom:12px;margin-bottom:20px}
.stmt-header h1{margin:0;font-size:22px;color:#2c5f2e;letter-spacing:2px}
.stmt-header h2{margin:4px 0 0;font-size:12px;font-weight:normal;color:#555}
.stmt-title{text-align:center;margin:0 0 20px}
.stmt-title span{font-size:16px;font-weight:bold;letter-spacing:3px;border:2px solid #2c5f2e;padding:4px 18px;color:#2c5f2e}
.meta-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 40px;margin-bottom:20px}
.meta-block h4{margin:0 0 6px;font-size:10px;text-transform:uppercase;color:#888;border-bottom:1px solid #ddd;padding-bottom:3px}
.meta-block p{margin:3px 0;font-size:13px}
.meta-block .lbl{color:#666;font-size:11px}
.section-title{font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.8px;border-bottom:2px solid #2c5f2e;padding-bottom:4px;margin:22px 0 10px;color:#2c5f2e}
table.detail-table{width:100%;border-collapse:collapse;margin-bottom:16px}
table.detail-table td{padding:8px 10px;font-size:13px;border-bottom:1px solid #eee}
.dt-lbl{background:#f0f7f0;font-weight:bold;font-size:11px;width:18%;color:#2c5f2e;white-space:nowrap}
.badge{display:inline-block;padding:2px 10px;border-radius:10px;font-size:11px;font-weight:bold}
.bg-completed{background:#d4edda;color:#155724}
.bg-draft{background:#e2e3e5;color:#383d41}
.parties-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 40px;margin-bottom:20px}
.party-block{padding:10px 0}
.party-block h4{margin:0 0 8px;font-size:10px;text-transform:uppercase;color:#888;border-bottom:1px solid #ddd;padding-bottom:3px}
.party-name{font-size:15px;font-weight:bold;margin-bottom:2px}
.party-title{font-size:12px;color:#666;font-style:italic}
.party-id{font-size:12px;color:#666;margin-bottom:4px}
.sig-line{border-bottom:1px solid #333;margin-top:40px;margin-bottom:4px}
.sig-label{font-size:10px;color:#888;text-transform:uppercase}
.witness-block{padding:10px 0;margin-bottom:10px}
.notes-box{border:1px solid #ddd;background:#fffef0;padding:10px 14px;white-space:pre-wrap;line-height:1.6;margin-bottom:16px}
.confirmation-box{background:#f0f7f0;border:2px solid #2c5f2e;padding:14px;margin:20px 0;font-size:13px;line-height:1.7;border-radius:4px}
.footer{border-top:1px solid #ddd;padding-top:10px;margin-top:20px;font-size:11px;color:#888;text-align:center}
